class ConfigManager:
    PROJECT_ROOT = Path(__file__).resolve().parent.parent
    CONFIG_FILE = PROJECT_ROOT / "config.json"

    def __init__(self):
        if not self.CONFIG_FILE.exists():
            raise FileNotFoundError(
                f"No se encontró el archivo de configuración: "
                f"{self.CONFIG_FILE}"
