from enum import Enum
from pathlib import Path
from typing import TypeAlias

from domain.youtube.video import Video
from domain.youtube.video_metadata import VideoMetadata


class OperationType(Enum):
    UPDATE_METADATA = "update_metadata"
    SET_THUMBNAIL = "set_thumbnail"
    ADD_TO_PLAYLIST = "add_to_playlist"


class OperationStatus(Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"


OperationData: TypeAlias = VideoMetadata | Path | str


class Operation:
    def __init__(
        self,
        video: Video,
        operation_type: OperationType,
        data: OperationData,
    ) -> None:
        self._validate_data(operation_type, data)

        self._video = video
        self._operation_type = operation_type
        self._status = OperationStatus.PENDING
        self._data = data

    @property
    def video(self) -> Video:
        return self._video

    @property
    def operation_type(self) -> OperationType:
        return self._operation_type

    @property
    def status(self) -> OperationStatus:
        return self._status

    @property
    def data(self) -> OperationData:
        return self._data

    def start(self) -> None:
        if self._status is not OperationStatus.PENDING:
            raise ValueError(
                "Only pending operations can be started."
            )

        self._status = OperationStatus.RUNNING

    def complete(self) -> None:
        if self._status is not OperationStatus.RUNNING:
            raise ValueError(
                "Only running operations can be completed."
            )

        self._status = OperationStatus.COMPLETED

    def fail(self) -> None:
        if self._status is not OperationStatus.RUNNING:
            raise ValueError(
                "Only running operations can be failed."
            )

        self._status = OperationStatus.FAILED

    def reset(self) -> None:
        if self._status is not OperationStatus.RUNNING:
            raise ValueError(
                "Only running operations can be reset."
            )

        self._status = OperationStatus.PENDING

    def retry(self) -> None:
        if self._status is not OperationStatus.FAILED:
            raise ValueError(
                "Only failed operations can be retried."
            )

        self._status = OperationStatus.PENDING

    @staticmethod
    def _validate_data(
        operation_type: OperationType,
        data: OperationData,
    ) -> None:
        expected_types = {
            OperationType.UPDATE_METADATA: VideoMetadata,
            OperationType.SET_THUMBNAIL: Path,
            OperationType.ADD_TO_PLAYLIST: str,
        }

        expected_type = expected_types[operation_type]

        if not isinstance(data, expected_type):
            raise TypeError(
                f"{operation_type.value} requires "
                f"{expected_type.__name__} data."
            )

from __future__ import annotations

from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


class PublicationSettings:
    def __init__(
        self,
        first_publish_at: datetime,
        timezone: str,
        interval_days: int,
    ) -> None:
        if not isinstance(first_publish_at, datetime):
            raise TypeError("first_publish_at must be a datetime.")

        if first_publish_at.tzinfo is not None:
            raise ValueError("first_publish_at must be a naive datetime.")

        if not isinstance(timezone, str):
            raise TypeError("timezone must be a string.")

        try:
            timezone_info = ZoneInfo(timezone)
        except ZoneInfoNotFoundError as exc:
            raise ValueError(f"Invalid timezone: {timezone!r}.") from exc

        if isinstance(interval_days, bool) or not isinstance(interval_days, int):
            raise TypeError("interval_days must be an integer.")

        if interval_days <= 0:
            raise ValueError("interval_days must be greater than zero.")

        self._first_publish_at = first_publish_at.replace(tzinfo=timezone_info)
        self._timezone = timezone_info
        self._interval_days = interval_days

    @property
    def first_publish_at(self) -> datetime:
        return self._first_publish_at

    @property
    def timezone(self) -> ZoneInfo:
        return self._timezone

    @property
    def interval_days(self) -> int:
        return self._interval_days

    def __repr__(self) -> str:
        return (
            "PublicationSettings("
            f"first_publish_at={self._first_publish_at!r}, "
            f"timezone={self._timezone.key!r}, "
            f"interval_days={self._interval_days!r}"
            ")"
        )

"""Domain validation types for the YouTube album workflow.

This module contains domain-level validation results and errors.
It does not perform infrastructure operations or modify remote state.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ValidationError:
    """Represents a single domain validation error."""

    field: str
    message: str


class ValidationResult:
    """Represents the result of validating a domain object."""

    def __init__(self, errors: list[ValidationError] | None = None) -> None:
        self._errors = list(errors) if errors is not None else []

    @property
    def is_valid(self) -> bool:
        """Return whether the validation completed without errors."""
        return not self._errors

    @property
    def errors(self) -> tuple[ValidationError, ...]:
        """Return the validation errors."""
        return tuple(self._errors)

    def add_error(self, field: str, message: str) -> None:
        """Add a validation error to the result."""
        self._errors.append(
            ValidationError(
                field=field,
                message=message,
            )
        )

