class JobMapper:
    def to_model(self, job: Job) -> JobModel:
        job_model = JobModel(
            status=job.status.value,
        )

        videos_by_id: dict[str, VideoModel] = {}

        job_model.operations = [
            self._operation_to_model(operation, videos_by_id)
            for operation in job.operations
        ]

        return job_model

    def update_model(self, job_model: JobModel, job: Job) -> None:
        job_model.status = job.status.value

        videos_by_id: dict[str, VideoModel] = {
            operation.video.video_id: operation.video
            for operation in job_model.operations
            if operation.video is not None
        }

        job_model.operations = [
            self._operation_to_model(operation, videos_by_id)
            for operation in job.operations
        ]

    def to_domain(self, job_model: JobModel) -> Job:
        operations = [
            self._operation_to_domain(operation_model)
            for operation_model in job_model.operations
        ]

        job = Job(operations)

        if job_model.status == JobStatus.RUNNING.value:
            job.start()
        elif job_model.status == JobStatus.COMPLETED.value:
            job.start()
            job.complete()
        elif job_model.status == JobStatus.FAILED.value:
            job.start()
            job.fail()

        return job

    def _operation_to_model(
        self,
        operation: Operation,
        videos_by_id: dict[str, VideoModel],
    ) -> OperationModel:
        operation_model = OperationModel(
            operation_type=operation.operation_type.value,
            status=operation.status.value,
        )

        video = videos_by_id.get(operation.video.video_id)

        if video is None:
            video = self._video_to_model(operation.video)
            videos_by_id[operation.video.video_id] = video

        operation_model.video = video
        operation_model.data = self._data_to_model(
            operation.operation_type,
            operation.data,
        )

        return operation_model

    def _operation_to_domain(
        self,
        operation_model: OperationModel,
    ) -> Operation:
        video = self._video_to_domain(operation_model.video)

        data = self._data_to_domain(
            operation_model.operation_type,
            operation_model.data,
        )

        operation = Operation(
            video=video,
            operation_type=OperationType(operation_model.operation_type),
            data=data,
        )

        if operation_model.status == OperationStatus.RUNNING.value:
            operation.start()
        elif operation_model.status == OperationStatus.COMPLETED.value:
            operation.start()
            operation.complete()
        elif operation_model.status == OperationStatus.FAILED.value:
            operation.start()
            operation.fail()

        return operation

    def _video_to_model(self, video: Video) -> VideoModel:
        return VideoModel(
            video_id=video.video_id,
            position=video.position,
            video_type=video.video_type.value,
        )

    def _video_to_domain(self, video_model: VideoModel) -> Video:
        return Video(
            video_id=video_model.video_id,
            position=video_model.position,
            video_type=VideoType(video_model.video_type),
            metadata=VideoMetadata(
                title="",
                description="",
                tags=None,
                playlists=[],
                game="",
                made_for_kids=False,
                contains_synthetic_media=False,
                publish_at=datetime.min.replace(tzinfo=timezone.utc),
                thumbnail=None,
            ),
        )

    def _data_to_model(
        self,
        operation_type: OperationType,
        data: OperationData,
    ) -> VideoMetadataModel:
        if operation_type is OperationType.UPDATE_METADATA:
            metadata = data

            return VideoMetadataModel(
                title=metadata.title,
                description=metadata.description,
                tags=(
                    json.dumps(metadata.tags)
                    if metadata.tags is not None
                    else None
                ),
                game=metadata.game,
                made_for_kids=metadata.made_for_kids,
                contains_synthetic_media=metadata.contains_synthetic_media,
                publish_at=metadata.publish_at.isoformat(),
                thumbnail=(
                    str(metadata.thumbnail)
                    if metadata.thumbnail is not None
                    else None
                ),
            )

        if operation_type is OperationType.SET_THUMBNAIL:
            return VideoMetadataModel(
                thumbnail=str(data),
            )

        if operation_type is OperationType.ADD_TO_PLAYLIST:
            return VideoMetadataModel(
                playlist=data,
            )

        raise ValueError(
            f"Unsupported operation type: {operation_type}"
        )

    def _data_to_domain(
        self,
        operation_type: str,
        data_model: VideoMetadataModel,
    ) -> OperationData:
        operation_type = OperationType(operation_type)

        if operation_type is OperationType.UPDATE_METADATA:
            tags = (
                json.loads(data_model.tags)
                if data_model.tags is not None
                else None
            )

            return VideoMetadata(
                title=data_model.title,
                description=data_model.description,
                tags=tags,
                playlists=[],
                game=data_model.game,
                made_for_kids=data_model.made_for_kids,
                contains_synthetic_media=data_model.contains_synthetic_media,
                publish_at=datetime.fromisoformat(data_model.publish_at),
                thumbnail=(
                    Path(data_model.thumbnail)
                    if data_model.thumbnail is not None
                    else None
                ),
            )

        if operation_type is OperationType.SET_THUMBNAIL:
            return Path(data_model.thumbnail)

        if operation_type is OperationType.ADD_TO_PLAYLIST:
            return data_model.playlist

        raise ValueError(
            f"Unsupported operation type: {operation_type}"
        )

from sqlalchemy import select
from sqlalchemy.orm import Session

from domain.youtube.job import Job
from domain.youtube.job_repository import JobRepository

from services.youtube.storage.mappers.job_mapper import JobMapper
from services.youtube.storage.models.job import JobModel


class YouTubeJobRepository(JobRepository):

    def __init__(self, session: Session, mapper: JobMapper):
        self._session = session
        self._mapper = mapper
        self._current_job_model: JobModel | None = None

    def find_pending(self) -> Job | None:
        statement = (
            select(JobModel)
            .where(JobModel.status == "pending")
            .order_by(JobModel.id)
            .limit(1)
        )

        job_model = self._session.scalars(statement).first()

        if job_model is None:
            return None

        self._current_job_model = job_model
        return self._mapper.to_domain(job_model)

    def find_failed(self) -> Job | None:
        statement = (
            select(JobModel)
            .where(JobModel.status == "failed")
            .order_by(JobModel.id)
            .limit(1)
        )

        job_model = self._session.scalars(statement).first()

        if job_model is None:
            return None

        self._current_job_model = job_model
        return self._mapper.to_domain(job_model)

    def save(self, job: Job) -> None:
        if self._current_job_model is not None:
            self._mapper.update_model(self._current_job_model, job)
        else:
            self._current_job_model = self._mapper.to_model(job)
            self._session.add(self._current_job_model)

        self._session.commit()
        self._current_job_model = None

from __future__ import annotations

from pathlib import Path

from domain.youtube.job import Job, JobStatus
from domain.youtube.job_repository import JobRepository
from domain.youtube.video_metadata import VideoMetadata
from domain.youtube.operation import (
    Operation,
    OperationStatus,
    OperationType,
)

from services.youtube.api.methods import (
    YouTubeMethods,
    YouTubeQuotaExceededError,
)


class Updater:
    """
    Executes the pending operations of a Job against YouTube.

    The Job already contains the desired data and the execution order.
    Updater only executes operations, manages execution state, handles
    retries and persists the resulting Job state.
    """

    def __init__(
        self,
        youtube_methods: YouTubeMethods,
        job_repository: JobRepository,
        max_attempts: int = 3,
    ) -> None:
        if max_attempts < 1:
            raise ValueError("max_attempts must be at least 1.")

        self._youtube_methods = youtube_methods
        self._job_repository = job_repository
        self._max_attempts = max_attempts

    def update(self, job: Job) -> None:
        """
        Execute a Job from its current state.

        Completed operations are skipped. Pending operations are executed in
        their existing order until the Job completes, quota is exhausted, or
        an operation fails definitively.
        """
        if job.status is JobStatus.PENDING:
            job.start()
        elif job.status is not JobStatus.RUNNING:
            raise ValueError(
                "Only pending or running jobs can be updated."
            )

        for operation in job.operations:
            if operation.status is OperationStatus.COMPLETED:
                continue

            if operation.status is not OperationStatus.PENDING:
                raise ValueError(
                    "A job can only contain pending or completed operations "
                    "during an update."
                )

            if self._execute_operation(job, operation):
                continue

            return

        job.complete()
        self._job_repository.save(job)

    def _execute_operation(self, job: Job, operation: Operation) -> bool:
        """Execute one pending operation and return whether it completed."""
        operation.start()

        for attempt in range(1, self._max_attempts + 1):
            try:
                self._dispatch(operation)
            except YouTubeQuotaExceededError:
                operation.reset()
                job.reset()
                self._job_repository.save(job)
                return False
            except Exception as error:
                self._report_operation_failure(operation, attempt, error)

                if attempt == self._max_attempts:
                    operation.fail()
                    job.fail()
                    self._job_repository.save(job)
                    self._report_job_failure(operation, error)
                    return False

                # The operation remains RUNNING between normal retry attempts.
                # The next API call is another attempt of the same operation.
                continue
            else:
                operation.complete()
                return True

        raise RuntimeError("Unreachable execution state.")

    def _dispatch(self, operation: Operation) -> None:
        """Dispatch an operation to the corresponding YouTube API method."""
        if operation.operation_type is OperationType.UPDATE_METADATA:
            metadata = self._require_data(operation, VideoMetadata)
            self._youtube_methods.videos_update(
                video_resource=self._build_video_resource(
                    operation.video.video_id,
                    metadata,
                )
            )
            return

        if operation.operation_type is OperationType.SET_THUMBNAIL:
            thumbnail_path = self._require_data(operation, Path)
            self._youtube_methods.thumbnails_set(
                video_id=operation.video.video_id,
                thumbnail_path=thumbnail_path,
            )
            return

        if operation.operation_type is OperationType.ADD_TO_PLAYLIST:
            playlist_id = self._require_data(operation, str)
            self._youtube_methods.playlist_items_insert(
                playlist_item_resource={
                    "snippet": {
                        "playlistId": playlist_id,
                        "resourceId": {
                            "kind": "youtube#video",
                            "videoId": operation.video.video_id,
                        },
                    }
                }
            )
            return

        raise ValueError(
            f"Unsupported operation type: {operation.operation_type}."
        )

    @staticmethod
    def _require_data(
        operation: Operation,
        expected_type: type,
    ):
        data = operation.data
        if not isinstance(data, expected_type):
            raise TypeError(
                f"{operation.operation_type.value} requires "
                f"{expected_type.__name__} data."
            )
        return data

    @staticmethod
    def _build_video_resource(
        video_id: str,
        metadata: VideoMetadata,
    ) -> dict:
        """Adapt domain metadata to the YouTube videos.update resource."""
        # YouTube's "Video games" category is fixed for this application.
        # The game name remains part of the domain metadata for future use.
        VIDEO_GAMES_CATEGORY_ID = "20"

        snippet = {
            "title": metadata.title,
            "description": metadata.description,
            "tags": list(metadata.tags) if metadata.tags is not None else [],
            "categoryId": VIDEO_GAMES_CATEGORY_ID,
        }

        status = {
            "privacyStatus": "private",
            "publishAt": metadata.publish_at.isoformat(),
            "selfDeclaredMadeForKids": metadata.made_for_kids,
            "containsSyntheticMedia": metadata.contains_synthetic_media,
        }

        return {
            "id": video_id,
            "snippet": snippet,
            "status": status,
        }

    @staticmethod
    def _report_operation_failure(
        operation: Operation,
        attempt: int,
        error: Exception,
    ) -> None:
        print(
            f"Operation failed "
            f"(video={operation.video.video_id}, "
            f"type={operation.operation_type.value}, "
            f"attempt={attempt}): {error}"
        )

    @staticmethod
    def _report_job_failure(
        operation: Operation,
        error: Exception,
    ) -> None:
        print(
            f"Job failed on operation "
            f"(video={operation.video.video_id}, "
            f"type={operation.operation_type.value}): {error}"
        )

from __future__ import annotations

from typing import Any

from domain.youtube.youtube_video import PrivacyStatus, YouTubeVideo
from services.youtube.api.methods import YouTubeMethods


class YouTubeDiscovery:
    """Discover the current album videos uploaded to YouTube."""

    def __init__(self, methods: YouTubeMethods) -> None:
        self._methods = methods

    def discover(self, expected_video_count: int) -> tuple[YouTubeVideo, ...]:
        """Discover the first continuous sequence of private videos."""

        if expected_video_count <= 0:
            raise ValueError("expected_video_count must be greater than zero.")

        uploads_playlist_id = self._get_uploads_playlist_id()

        videos: list[YouTubeVideo] = []
        found_private_block = False
        page_token: str | None = None

        while True:
            response = self._methods.playlist_items_list(
                playlist_id=uploads_playlist_id,
                page_token=page_token,
            )

            for item in response.get("items", []):
                video = self._map_video(item)

                if video.privacy_status is PrivacyStatus.PRIVATE:
                    found_private_block = True
                    videos.append(video)
                    if len(videos) == expected_video_count:
                        return tuple(videos)
                    continue

                if found_private_block:
                    return tuple(videos)

            page_token = response.get("nextPageToken")

            if page_token is None:
                return tuple(videos)

    def _get_uploads_playlist_id(self) -> str:
        """Return the authenticated user's uploads playlist ID."""

        response = self._methods.channels_list()

        items = response.get("items", [])

        if not items:
            raise RuntimeError("Authenticated YouTube channel was not found.")

        playlist_id = (
            items[0]
            .get("contentDetails", {})
            .get("relatedPlaylists", {})
            .get("uploads")
        )

        if not playlist_id:
            raise RuntimeError("YouTube uploads playlist was not found.")

        return playlist_id

    @staticmethod
    def _map_video(item: dict[str, Any]) -> YouTubeVideo:
        """Create a YouTubeVideo from a playlist item."""

        content_details = item.get("contentDetails", {})
        snippet = item.get("snippet", {})
        status = item.get("status", {})

        return YouTubeVideo(
            video_id=content_details["videoId"],
            title=snippet["title"],
            description=snippet.get("description"),
            privacy_status=PrivacyStatus(status["privacyStatus"]),
        )
